<?php
require_once __DIR__.'/foundation.php';
function oecrm_payroll_item_details($conn,$itemId,$companyId=0){$sql='SELECT p.*,r.period_year,r.period_month,r.status payroll_status,r.company_id,e.employeeCode,e.name,e.designation,e.companyEmail,e.personalEmail,e.bankName,e.bankIFSCno,e.bankAcHolderName,e.bankAcNo,s.basic_salary,s.hra,s.special_allowance,s.other_allowance,c.legal_name,c.display_name,c.address company_address,c.email company_email,c.phone company_phone,c.gstin,c.currency_code FROM payroll_items p JOIN payroll_runs r ON r.id=p.payroll_run_id JOIN employeestbl e ON e.id=p.employee_id JOIN salary_structures s ON s.id=p.salary_structure_id JOIN companies c ON c.id=r.company_id WHERE p.id=?'.($companyId?' AND r.company_id=?':'');$stmt=mysqli_prepare($conn,$sql);if($companyId)mysqli_stmt_bind_param($stmt,'ii',$itemId,$companyId);else mysqli_stmt_bind_param($stmt,'i',$itemId);mysqli_stmt_execute($stmt);$r=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);return $r;}
function oecrm_money($amount,$currency='INR'){return ($currency==='INR'?'Rs. ':$currency.' ').number_format((float)$amount,2);}
function oecrm_salary_slip_html($item,$logoPath){ob_start();?>
<section class="salary-slip-document"><header><img src="<?php echo htmlspecialchars($logoPath);?>" alt="Company logo"><div><h1><?php echo htmlspecialchars($item['display_name']);?></h1><p><?php echo htmlspecialchars($item['company_address']);?></p><?php if($item['gstin']):?><small>GSTIN: <?php echo htmlspecialchars($item['gstin']);?></small><?php endif;?></div><div class="slip-period"><span>Salary Slip</span><strong><?php echo date('F Y',mktime(0,0,0,$item['period_month'],1,$item['period_year']));?></strong></div></header><div class="employee-slip-details"><div><small>Employee</small><strong><?php echo htmlspecialchars($item['name']);?></strong></div><div><small>Employee Code</small><strong><?php echo htmlspecialchars($item['employeeCode']);?></strong></div><div><small>Designation</small><strong><?php echo htmlspecialchars($item['designation']);?></strong></div><div><small>Bank Account</small><strong><?php echo htmlspecialchars($item['bankAcNo']?:'Not provided');?></strong></div></div><div class="slip-tables"><table><thead><tr><th>Earnings</th><th>Amount</th></tr></thead><tbody><tr><td>Basic Salary</td><td><?php echo oecrm_money($item['basic_salary'],$item['currency_code']);?></td></tr><tr><td>HRA</td><td><?php echo oecrm_money($item['hra'],$item['currency_code']);?></td></tr><tr><td>Special Allowance</td><td><?php echo oecrm_money($item['special_allowance'],$item['currency_code']);?></td></tr><tr><td>Other Allowance</td><td><?php echo oecrm_money($item['other_allowance'],$item['currency_code']);?></td></tr><tr><td>Overtime / Extra Days</td><td><?php echo oecrm_money($item['overtime_amount']+$item['extra_day_amount'],$item['currency_code']);?></td></tr></tbody><tfoot><tr><th>Gross Earnings</th><th><?php echo oecrm_money($item['gross_salary']+$item['overtime_amount']+$item['extra_day_amount'],$item['currency_code']);?></th></tr></tfoot></table><table><thead><tr><th>Deductions</th><th>Amount</th></tr></thead><tbody><tr><td>Attendance Deduction</td><td><?php echo oecrm_money($item['attendance_deduction'],$item['currency_code']);?></td></tr><tr><td>Unpaid Leave</td><td><?php echo oecrm_money($item['leave_deduction'],$item['currency_code']);?></td></tr><tr><td>Professional Tax</td><td><?php echo oecrm_money($item['professional_tax'],$item['currency_code']);?></td></tr><tr><td>Retention</td><td><?php echo oecrm_money($item['retention_amount'],$item['currency_code']);?></td></tr><tr><td>Other Deductions</td><td><?php echo oecrm_money($item['custom_deduction'],$item['currency_code']);?></td></tr></tbody><tfoot><tr><th>Total Deductions</th><th><?php echo oecrm_money($item['total_deduction'],$item['currency_code']);?></th></tr></tfoot></table></div><div class="attendance-slip-summary"><div><small>Calendar Days</small><strong><?php echo (int)$item['calendar_days'];?></strong></div><div><small>Present Days</small><strong><?php echo number_format($item['present_days'],1);?></strong></div><div><small>Paid Leave</small><strong><?php echo number_format($item['paid_leave_days'],1);?></strong></div><div><small>Unpaid Leave</small><strong><?php echo number_format($item['unpaid_leave_days'],1);?></strong></div><div><small>Effective Hours</small><strong><?php echo sprintf('%02d:%02d',intdiv((int)$item['effective_minutes'],60),(int)$item['effective_minutes']%60);?></strong></div></div><div class="net-salary"><span>Net Salary Payable</span><strong><?php echo oecrm_money($item['net_salary'],$item['currency_code']);?></strong></div><footer><span>This is a computer-generated salary slip and does not require a signature.</span><span>Generated on <?php echo date('d M Y');?></span></footer></section><?php return ob_get_clean();}
function oecrm_salary_slip_styles(){return '<style>*{box-sizing:border-box}body{margin:0;background:#eef0f5;font-family:Arial,sans-serif;color:#333}.print-toolbar{display:flex;justify-content:flex-end;gap:8px;max-width:900px;margin:18px auto}.print-toolbar button,.print-toolbar a{padding:9px 14px;border:0;border-radius:6px;background:#696cff;color:#fff;text-decoration:none;cursor:pointer}.salary-slip-document{width:900px;min-height:1120px;margin:0 auto 24px;padding:38px;background:#fff;box-shadow:0 4px 22px rgba(0,0,0,.1);page-break-after:always}.salary-slip-document header{display:grid;grid-template-columns:120px 1fr auto;align-items:center;gap:18px;padding-bottom:22px;border-bottom:2px solid #696cff}.salary-slip-document header img{max-width:110px;max-height:65px}.salary-slip-document h1{margin:0 0 5px;font-size:21px}.salary-slip-document header p{margin:0;color:#777;font-size:11px}.slip-period{text-align:right}.slip-period span,.slip-period strong{display:block}.slip-period span{color:#696cff;font-size:20px;font-weight:bold}.employee-slip-details,.attendance-slip-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:22px 0}.employee-slip-details div,.attendance-slip-summary div{padding:11px;background:#f7f7fb;border-radius:6px}.salary-slip-document small{display:block;margin-bottom:4px;color:#888;font-size:10px}.slip-tables{display:grid;grid-template-columns:1fr 1fr;gap:18px}.slip-tables table{width:100%;border-collapse:collapse}.slip-tables th,.slip-tables td{padding:11px;border:1px solid #e3e4ec;text-align:left;font-size:12px}.slip-tables th:last-child,.slip-tables td:last-child{text-align:right}.slip-tables thead{background:#696cff;color:#fff}.slip-tables tfoot{background:#f0f1ff}.attendance-slip-summary{grid-template-columns:repeat(5,1fr)}.net-salary{display:flex;align-items:center;justify-content:space-between;margin-top:20px;padding:18px 20px;border-radius:7px;background:#eaf8e4;color:#31920f}.net-salary strong{font-size:22px}.salary-slip-document footer{display:flex;justify-content:space-between;margin-top:35px;padding-top:14px;border-top:1px solid #ddd;color:#888;font-size:9px}@media print{body{background:#fff}.print-toolbar{display:none}.salary-slip-document{width:100%;min-height:auto;margin:0;padding:20px;box-shadow:none}}@media(max-width:920px){.salary-slip-document{width:100%;min-height:auto}.slip-tables{grid-template-columns:1fr}.employee-slip-details,.attendance-slip-summary{grid-template-columns:repeat(2,1fr)}}</style>';}